  await page.goto('file:///app/poster.html', { waitUntil: 'networkidle0' });

  // Optional: wait a moment for fonts to load
  await page.evaluate(async () => {
    await document.fonts.ready;
  });

  await page.screenshot({ path: '/app/output/final_poster.png' });

  await browser.close();
})();

